@staticmethod
def promote(lin: LinOp, view: SciPyTensorView) -> SciPyTensorView:
    """
    Promote view by repeating along axis 0 (rows).
    """
    num_entries = int(np.prod(lin.shape))
    rows = np.zeros(num_entries).astype(int)
    view.select_rows(rows)
    return view

